<script setup lang="ts">
import { computed, ref, watch, onUnmounted } from 'vue'
import { useRoute } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { ChatbubblesOutline, FolderOpenOutline } from '@vicons/ionicons5'
import { useDataStore } from '../stores/data'
import { useWorkspaceStore } from '../stores/workspace'
import FileTree from '../components/FileTree.vue'
const route=useRoute();const {t}=useI18n();const data=useDataStore();const workspace=useWorkspaceStore();const files=ref(window.innerWidth>=1180);const projects=ref(true);const query=ref('');const width=ref(260)
const project=computed(()=>data.projects.find(p=>p.id===route.params.projectId));const connection=computed(()=>data.connections.find(c=>c.id===project.value?.connectionId));const listed=computed(()=>data.projects.filter(p=>!p.archived&&p.name.toLowerCase().includes(query.value.toLowerCase())))
watch(project,p=>{workspace.projectId=p?.id??'';if(p)localStorage.setItem('agentdesk-last-project',p.id)},{immediate:true})
function resized(){if(window.innerWidth<1180)files.value=false}
window.addEventListener('resize',resized);onUnmounted(()=>window.removeEventListener('resize',resized))
let stopDrag:(()=>void)|undefined
function resizeProjects(event:PointerEvent){event.preventDefault();const start=event.clientX;const initial=width.value;const move=(e:PointerEvent)=>width.value=Math.max(180,Math.min(360,initial+e.clientX-start));const stop=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop)};stopDrag=stop;window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop,{once:true})}
onUnmounted(()=>stopDrag?.())
</script>
<template><section class="workbench"><aside v-if="projects" class="project-panel" :style="{width:width+'px'}"><div class="project-tools"><n-input v-model:value="query" size="small" :placeholder="t('common.search')"/><n-button size="tiny" @click="projects=false">‹</n-button></div><router-link v-for="p in listed" :key="p.id" :to="'/workbench/'+p.id" class="project-link"><FolderOpenOutline/><div><strong>{{ p.pinned?'★ ':'' }}{{ p.name }}</strong><small>{{ data.connections.find(c=>c.id===p.connectionId)?.name }}</small></div></router-link><router-link to="/projects" class="manage-projects">{{ t('projects.new') }}</router-link><div class="project-resize" role="separator" @pointerdown="resizeProjects"/></aside><div class="chat-area"><template v-if="project"><header class="workbench-head"><div class="target-copy"><div class="actions"><n-button v-if="!projects" size="tiny" @click="projects=true">›</n-button><strong>{{ project.name }}</strong><span class="status" :class="data.statuses[project.connectionId]?.state">{{ t('state.'+(data.statuses[project.connectionId]?.state??'disconnected')) }}</span></div><p class="mono muted">{{ connection?.name }} · {{ connection?.user }}@{{ connection?.host }} : {{ project.path }}</p></div><div class="actions"><n-button size="small" :disabled="!data.online(project.connectionId)" @click="workspace.openTerminal(project)">{{ t('workbench.shell') }}</n-button><n-dropdown trigger="click" :options="[{label:'Claude Code',key:'claude'},{label:'Codex',key:'codex'}]" @select="(kind:'claude'|'codex')=>workspace.openTerminal(project!,kind)"><n-button size="small" :disabled="!data.online(project.connectionId)">{{ t('workbench.terminal') }} ▾</n-button></n-dropdown><n-button size="small" @click="files=!files">{{ t('workbench.files') }}</n-button><n-button size="small" @click="workspace.dockOpen=!workspace.dockOpen">{{ t('workbench.terminal') }} ↕</n-button></div></header><n-alert v-if="!data.online(project.connectionId)" type="warning" class="connection-warning">{{ t('workbench.disconnected') }} <router-link to="/connections">{{ t('nav.connections') }}</router-link></n-alert><div class="agent-empty empty"><ChatbubblesOutline/><h2>{{ t('workbench.agentLater') }}</h2><p>{{ t('workbench.agentHelp') }}</p><span class="execution-label mono">{{ t('workbench.remote') }} · {{ project.path }}</span></div></template><div v-else class="empty no-project"><FolderOpenOutline/><h2>{{ t('workbench.noProject') }}</h2><p>{{ t('workbench.noProjectHelp') }}</p><router-link to="/projects">{{ t('nav.projects') }}</router-link></div></div><div v-if="project&&files" class="file-panel"><FileTree v-if="data.online(project.connectionId)" :project="project" :key="project.id"/><div v-else class="empty">{{ t('workbench.disconnected') }}</div></div></section></template>
<style scoped>.workbench{height:100%;display:flex;overflow:hidden;min-width:0}.project-panel{flex:none;position:relative;background:var(--surface1);border-right:1px solid var(--border);display:flex;flex-direction:column;min-width:0;padding:14px 10px;overflow:auto}.project-tools{display:flex;gap:6px;margin-bottom:14px}.project-link{display:flex;align-items:center;gap:10px;padding:12px;border-radius:7px;color:var(--text)}.project-link svg{width:18px;color:var(--muted)}.project-link small{display:block;color:var(--muted);font-size:11px;margin-top:4px}.project-link.router-link-active{background:var(--surface2);color:var(--primary)}.manage-projects{margin-top:auto;padding:14px;font-size:12px}.project-resize{position:absolute;top:0;bottom:0;right:-3px;width:6px;cursor:col-resize;z-index:2}.chat-area{display:flex;flex-direction:column;min-width:0;flex:1}.workbench-head{min-height:92px;display:flex;justify-content:space-between;align-items:center;padding:18px 22px;gap:12px;border-bottom:1px solid var(--border);background:var(--surface1);flex-wrap:wrap}.target-copy{min-width:0;flex:1}.target-copy p{font-size:11px;margin:8px 0 0;overflow-wrap:anywhere}.agent-empty{flex:1}.agent-empty h2{font-size:18px}.execution-label{border:1px solid var(--border);border-radius:5px;padding:7px 10px;font-size:11px;margin-top:14px}.no-project{flex:1}.file-panel{flex:none;width:290px;min-width:0}.connection-warning{margin:12px;width:calc(100% - 24px)}@media(max-width:1179px){.file-panel{position:absolute;right:0;top:40px;bottom:0;width:300px;z-index:15;box-shadow:-8px 0 26px #0002}.workbench-head{padding:15px}.project-panel{max-width:220px}}</style>
